[CmdletBinding()]param([string]$OutputDirectory=(Join-Path (Split-Path -Parent (Split-Path -Parent (Split-Path -Parent $PSScriptRoot))) '_import\system-cleanup-v1.0.0\build'))
$ErrorActionPreference='Stop';New-Item -ItemType Directory -Path $OutputDirectory -Force|Out-Null;$zip=Join-Path $OutputDirectory 'KI-Stack-System-Cleanup-v1.0.0.zip';if(Test-Path $zip){Remove-Item $zip -Force};$files=Get-ChildItem $PSScriptRoot -Recurse -File|Where-Object{$_.FullName-notmatch'[\\/]Output[\\/]'}|Sort-Object{$_.FullName.Substring($PSScriptRoot.Length).Replace('\','/')};$epoch=[datetime]'2020-01-01T00:00:00Z';$stream=[IO.File]::Open($zip,[IO.FileMode]::CreateNew);try{$archive=[IO.Compression.ZipArchive]::new($stream,[IO.Compression.ZipArchiveMode]::Create);try{foreach($f in $files){$rel=$f.FullName.Substring($PSScriptRoot.Length).TrimStart('\').Replace('\','/');$e=$archive.CreateEntry("KI-Stack-System-Cleanup-v1.0.0/$rel",[IO.Compression.CompressionLevel]::Optimal);$e.LastWriteTime=$epoch;$src=$f.OpenRead();$dst=$e.Open();try{$src.CopyTo($dst)}finally{$dst.Dispose();$src.Dispose()}}}finally{$archive.Dispose()}}finally{$stream.Dispose()};$hash=(Get-FileHash $zip -Algorithm SHA256).Hash.ToLowerInvariant();"$hash *$([IO.Path]::GetFileName($zip))"|Set-Content "$zip.sha256" -Encoding ascii;[pscustomobject]@{zip=$zip;sha256=$hash;sizeBytes=(Get-Item $zip).Length}|ConvertTo-Json
